import{_ as l,c as i,o as e,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"《杂卦传》","description":"周易折中 - 《杂卦传》","frontmatter":{"title":"《杂卦传》","description":"周易折中 - 《杂卦传》"},"headers":[],"relativePath":"zh/classics/zhezhong/077.md","filePath":"zh/classics/zhezhong/077.md"}'),h={name:"zh/classics/zhezhong/077.md"};function p(n,a,d,t,s,o){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="《杂卦传》" tabindex="-1">《杂卦传》 <a class="header-anchor" href="#《杂卦传》" aria-label="Permalink to “《杂卦传》”">​</a></h1><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：序卦依文王上下而次序之，此杂卦孔子更以意错杂而对辨其次第，不与序卦同。</p></li><li><p>朱子语类云 ：卦有反有对，乾坤坎离是反，艮兑震巽是对。乾坤坎离倒转，也只是四卦。艮兑震巽倒转则为中孚颐小过大过，其馀皆是对卦。 又云：八卦便只是六卦，乾坤坎离是四正卦，兑便是翻转底巽，震便是翻转的艮。六十四卦只八卦是正卦，馀便只二十四卦翻转为五十六卦。中孚是个双夹底离，小过是个双夹的坎，大过是个厚画底坎，颐是个厚画底离。 又云：三画之卦只是六卦，即六画之卦以正卦八加反卦二十有八为三十有六，六六三十六也。邵子谓之暗卦，小成之卦八即大成之卦六十四，八八六十四也。三十六与六十四同。</p></li><li><p>又云：八卦便只是六卦，乾坤坎离是四正卦，兑便是翻转底巽，震便是翻转的艮。六十四卦只八卦是正卦，馀便只二十四卦翻转为五十六卦。中孚是个双夹底离，小过是个双夹的坎，大过是个厚画底坎，颐是个厚画底离。</p></li><li><p>又云：三画之卦只是六卦，即六画之卦以正卦八加反卦二十有八为三十有六，六六三十六也。邵子谓之暗卦，小成之卦八即大成之卦六十四，八八六十四也。三十六与六十四同。</p></li><li><p>龙氏仁夫曰 ：桉春秋传释系辞所谓屯固比入坤安震杀之属以一字断卦义，往往古筮书多有之，杂卦此类是也。夫子存之为经，羽翼非创作也。</p></li></ul><p>《乾》刚《坤》柔，《比》乐《师》忧；</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：有亲则乐，动众则忧。</p></li><li><p>朱氏震曰 ：比得位而众比之，故乐；师犯难而众从之，故忧。忧乐以天下也。</p></li></ul><p>《临》《观》之义，或与或求。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>以我临物曰与，物来观我曰求。或曰二卦互有与求之义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：临与所临，观与所观，二卦皆有与求之义。或有与无求，或有求无与，皆非临观之道。</li></ul><p>《屯》见而不失其居。《蒙》杂而著。</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>屯震遇坎震动，故见；坎险不行，也蒙坎遇艮坎幽昧，艮光明也。或曰屯以初言，蒙以二言。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：君子以经纶，故曰见；盘桓利居贞，故曰不失其居；蒙以养正，蒙正未分，故曰杂；童明，故曰著。</p></li><li><p>龚氏原曰 ：不见则不足以济众，不居则不足以为主。</p></li><li><p>柴氏中行曰 ：在蒙昧之中，虽未有识别，而善理昭著。</p></li></ul><p>《震》，起也。《艮》，止也。《损》、《益》盛衰之始也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：震阳动行，故起；艮阳终止，故止。</p></li><li><p>朱氏震曰 ：阳起于坤而出震，则静者动；阳止于艮而入坤，则动者静。</p></li><li><p>郭氏雍曰 ：损己必盛，故为盛之始；益己必衰，故为衰之始。消长相循，在道常如是也。</p></li><li><p>俞氏琰曰 ：损益盖未至于盛衰，而盛衰自此始也。</p></li><li><p>钱氏志立曰 ：损益否泰，为盛衰反复之介。易所最重者也。杂卦于他卦分举，而损益否泰则合举之，以明盛衰之无常，反复之甚速也。周易自乾坤至否泰十二卦，自咸恒至损益十二卦，此除乾坤外，自比师至损益十卦，自咸恒至泰否十卦。</p></li></ul><p>《大畜》，时也。《无妄》，灾也。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>止健者时，有适然无妄，而灾自外至。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：君子藏器于身，待时而动。然则多识前言往行，以畜其德，亦以待时也。无妄之谓灾，其馀自作孽而已，故无妄匪正，有眚。</p></li><li><p>何氏楷曰 ：大畜若上九天衢之亨，可谓得时矣。然无畜而时不谓时也，大畜故谓之时耳。无妄若六三或系之牛，可谓逢灾矣。然有妄而灾不谓灾也，无妄故谓之灾耳。</p></li></ul><p>《萃》聚而《升》不来也。《谦》轻而《豫》怠也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：谦轻已豫，怠已也。以乐豫故心怠，是以君子贵知止。</p></li><li><p>朱子语类云 ：轻是不自尊重卑小之义，豫是悦之极便放倒了，如上六冥豫是也。</p></li><li><p>项氏安世曰 ：自以为少故谦，自以为多故豫。少故轻，多故怠。</p></li><li><p>柴氏中行曰 ：谦者视己若甚轻，豫则有满盈之志而怠矣。</p></li><li><p>张氏振渊曰 ：萃有聚而尚往之义，升有往而不反之义。</p></li></ul><p>《噬嗑》，食也。《贲》，无色也。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>白受采。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：贲以白贲无咎，故无色则质全，有天下之至贲存焉。</p></li><li><p>项氏安世曰 ：物消曰食，噬者合则强，物消矣。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>此二语之义即所谓食取其充腹，衣取其蔽体者也。若饫于膏梁，则噬之不能合而失饮食之正；若竞于华美，则目迷五色而非自然之文。</p><p>《兑》见而《巽》伏也。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>兑阴外见，巽阴内伏。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：巽本以阴在下为能巽也，彖传乃为刚巽乎中正而志行柔皆顺乎刚；兑本以阴在上为能说也，彖传乃谓刚中而柔外说以利贞，盖终主阳也云尔。</li></ul><p>《随》无故也。《蛊》则饬也。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>随前无故，蛊后当饬。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：故谓故旧，与革去故之故同，随人则忘旧，蛊则饬而新也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>无故犹荘子言去故，人心有旧见，则不能随人，故尧舜舎己从人者无故也。</p><p>《剥》，烂也。《复》，反也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：剥烂尽复反生也，凡果烂而仁生，物烂而蛊生，木叶烂而根生，粪壤烂而苗生，皆剥复之理也。</p></li><li><p>徐氏㡬曰 ：剥烂则阳穷于上，复反则阳生于下，犹果之烂坠于下，则可种而生矣。</p></li></ul><p>《晋》，昼也。《明夷》，诛也。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>诛伤也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：离日在上故昼也，明入地中故诛也。</p></li><li><p>郭氏雍曰 ：晋与明夷朝暮之象也，故言明出地上，明入地中诛亦伤也。</p></li></ul><p>《井》通而《困》相遇也。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>刚柔相遇而刚见揜也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：泽无水理势适然，故曰相遇。</p></li><li><p>朱氏震曰 ：往来不穷故曰井通，遇阴则见揜而困，惟其时也。</p></li><li><p>郭氏雍曰 ：往来井井，则其道通；困遇刚揜，所以为困。</p></li><li><p>项氏安世曰 ：自乾坤至此三十卦，正与上经之数相当，而下经亦以咸恒为始，以见卦虽以杂名，而乾坤咸恒上下经之首，则未尝杂也。</p></li></ul><p>《咸》速也。《恒》，久也。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>咸速恒久。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏渊曰 ：有感则应，故速；常故能久。</p></li><li><p>蔡氏清曰 ：咸非训速也，天下之事无速于感通者；坎曰咸速。</p></li></ul><p>《涣》，离也。《节》，止也。《解》，缓也。《蹇》，难也。《睽》，外也。《家人》，内也。《否》、《泰》反其类也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：涣散故离，节制度数故止。</p></li><li><p>张子曰 ：天下之难既解，故安于佚乐，毎失于缓；蹇者见险而止，故为难。</p></li><li><p>项氏安世曰 ：涣节正与井困相反；井以木出水居，塞而能通；涣则以水浮木，故通之极而至于散也；节以泽上之水居，通而能塞；困为泽下之水，故塞之极而至于困也。</p></li><li><p>徐氏㡬曰 ：睽者疏而外也，家人者亲而内也。</p></li><li><p>俞氏琰曰 ：涣节皆有坎水，风以散之则离，泽以潴之则止。</p></li></ul><p>《大壮》则止，《遯》则退也。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>止谓不进。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：壮不知止，小人之壮也；君子之壮，则有止；遁之退，大壮之止，则克己之道。</p></li><li><p>赵氏玉泉曰 ：大壮以壮趾为凶，用壮为厉，欲阳之知所止也；遁以嘉遁为吉，肥遁为利，欲阳之知所处也。</p></li><li><p>何氏楷曰 ：壮不可用，宜止不宜躁；遁与时行，应退不应进；止者难进，退者易；退也。</p></li></ul><p>《大有》，众也。《同人》，亲也。《革》，去故也。《鼎》，取新也。《小过》，过也。《中孚》，信也。《丰》，多故也。亲寡《旅》也。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>既明且动，其故多矣。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱氏震曰 ：大有六五柔得尊位，而有其众；有其众，则众亦归之，故曰大有众也。同人六二得中得位，而同乎人；同乎人，则人亦亲之，故曰同人亲也。</li></ul><p>《离》上而《坎》下也。《小畜》，寡也。《履》，不处也。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>不处行进之义。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>寡者一阴虽得位，而畜众阳，其力寡也；不处者一阴不得位，而行乎众阳之中，不敢宁处也。</p><p>《需》，不进也。《讼》，不亲也。</p><h3 id="集说-17" tabindex="-1">集说 <a class="header-anchor" href="#集说-17" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏舜臣曰 ：干上离下为同人，火性炎上而趋干，故曰同人亲也；干上坎下为讼，水性就下与干违行，故不亲也。</li></ul><p>《大过》，颠也。《姤》，遇也，柔遇刚也。《渐》，女归待男行也。《颐》，养正也。《既济》，定也。《归妹》，女之终也。《未济》，男之穷也。《夬》，决也，刚决柔也。君子道长，小人道忧也。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>自大过以下卦，不反对或疑其错简。今以韵协之，又似非误，未详何义。</p><h3 id="集说-18" tabindex="-1">集说 <a class="header-anchor" href="#集说-18" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>韩氏伯曰：刚柔失位，其道未济，故曰穷也。</p></li><li><p>朱子语类云：女待男而行，所以为渐。</p></li><li><p>又云：杂卦以干为首，不终之以他卦，而必终之以夬者，盖夬以五阳决一阴，决去一阴，则复为纯干矣。</p></li><li><p>项氏安世曰：大过之象，本末俱弱，而在杂卦之终。圣人作易，示天下以无终穷之理，教人以拨乱反正之法。是故原其乱之始，生于姤，而极其势之上穷于夬，以示㣲之当防，盛之不足畏。自夬而干，有终而复始之义也。</p></li><li><p>又曰：自大过以下，特皆以男女为言，至夬而明言之曰君子小人。然则圣人之意，断可识矣。</p></li><li><p>胡氏炳文曰：本义谓自大过以下或疑其错简，以韵协之，又似非误。愚窃以为杂物撰徳，非其中爻不备。此盖指中四爻互体而言也。先天图之左，互复颐既济家人归妹睽夬干八卦；右互姤大过未济解渐蹇剥坤八卦。此则于右取姤大过未济渐四卦，于左取颐既济归妹夬四卦，各举其半，可兼其馀矣。始于干，终于夬，夬之一阴决尽，则为干。</p></li></ul>',90)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
